<?php
/**
 * Pinterest integration: pins meal plans and recipes to a board via the
 * Pinterest API v5, mirroring the Instagram module (meta box with immediate
 * and scheduled publishing, REST endpoints for automation). Pin images are
 * the ones generated by the Instagram renderer, and every pin links back to
 * the plan/recipe page.
 *
 * @package MixMyMeals/Includes
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Pinterest pinning for meal plans and recipes.
 */
class Mixmymeals_Pinterest {

	const POST_TYPE        = 'mmm_meal_plan';
	const RECIPE_POST_TYPE = 'mmm_recipe';

	const OPTION_PREFIX = 'mixmymeals_pinterest_';
	const NONCE_ACTION  = 'mmm_pinterest';
	const API_BASE      = 'https://api.pinterest.com/v5';

	/** Wo der Nutzer die App autorisiert (nicht die API-Domain). */
	const OAUTH_AUTHORIZE_URL = 'https://www.pinterest.com/oauth/';

	/**
	 * Alle Scopes, die dieses Modul benutzt:
	 *
	 *   user_accounts:read  token_status() → GET /user_account (Anzeige „Verbunden als @…“)
	 *   boards:read         boards()       → GET /boards       (Board-Auswahl im Profil)
	 *   boards:write        publish_now()  → POST /pins        (verlangt Pinterest mit)
	 *   pins:read/write     publish_now()  → POST /pins
	 *
	 * Fehlt einer davon, scheitert genau die zugehörige Funktion — deshalb hier
	 * vollständig halten und nicht auf das Nötigste zum Pinnen kürzen.
	 */
	const OAUTH_SCOPES = 'user_accounts:read,boards:read,boards:write,pins:read,pins:write';

	/** Transient-Präfix des CSRF-State zwischen Start und Rückkehr. */
	const OAUTH_STATE_PREFIX = 'mmm_pin_oauth_';

	const PUBLISH_HOOK = 'mixmymeals_pinterest_scheduled_publish';

	const META_SCHEDULED_AT    = '_mmm_pin_scheduled_at';
	const META_SCHEDULED_TITLE = '_mmm_pin_scheduled_title';
	const META_SCHEDULED_DESC  = '_mmm_pin_scheduled_desc';
	const META_SCHEDULED_USER  = '_mmm_pin_scheduled_user';

	// User-meta prefix of the per-user credential set.
	const USER_META_PREFIX = 'mmm_pinterest_';
	const META_LAST_RESULT     = '_mmm_pin_last_result';

	// Pinterest field limits.
	const TITLE_MAX = 100;
	const DESC_MAX  = 800;

	public function __construct() {

		add_action( 'add_meta_boxes_' . self::POST_TYPE, array( $this, 'add_meta_box' ) );
		add_action( 'add_meta_boxes_' . self::RECIPE_POST_TYPE, array( $this, 'add_meta_box' ) );
		add_action( 'admin_enqueue_scripts', array( $this, 'enqueue_assets' ) );

		add_action( 'wp_ajax_mmm_pinterest_pin', array( $this, 'ajax_pin' ) );
		add_action( 'wp_ajax_mmm_pinterest_schedule', array( $this, 'ajax_schedule' ) );
		add_action( 'wp_ajax_mmm_pinterest_unschedule', array( $this, 'ajax_unschedule' ) );

		add_action( self::PUBLISH_HOOK, array( $this, 'run_scheduled_publish' ) );

		add_action( 'rest_api_init', array( $this, 'register_rest_routes' ) );

		// OAuth: Rückkehr von Pinterest auf der Profilseite abfangen.
		add_action( 'admin_init', array( $this, 'handle_oauth_callback' ) );
		add_action( 'admin_notices', array( $this, 'oauth_notice' ) );

		// Piggyback on the Instagram daily cron for the token refresh.
		if ( class_exists( 'Mixmymeals_Instagram' ) ) {
			add_action( Mixmymeals_Instagram::CRON_HOOK, array( __CLASS__, 'maybe_refresh_token' ) );
		}
	}

	/* ---------------------------------------------------------------------
	 * Options / API layer
	 * ------------------------------------------------------------------ */

	/**
	 * Reads one module option.
	 *
	 * @param string $key     Option key without prefix.
	 * @param mixed  $fallback Default value.
	 * @return mixed
	 */
	private static function opt( string $key, $fallback = '' ) {
		return get_option( self::OPTION_PREFIX . $key, $fallback );
	}

	/* ---------------------------------------------------------------------
	 * Credential context: strictly per-user accounts (mirrors
	 * Mixmymeals_Instagram). Every user's credential set lives in user
	 * meta (mmm_pinterest_*); there is deliberately no site-wide fallback.
	 * ------------------------------------------------------------------ */

	/**
	 * Explicit acting user; null = current user, 0 = site account.
	 *
	 * @var int|null
	 */
	private static ?int $acting_user = null;

	/**
	 * Sets (or resets, with null) the acting user for credential resolution.
	 *
	 * @param int|null $user_id User ID, 0 for the site account, null to reset.
	 * @return void
	 */
	public static function set_acting_user( ?int $user_id ): void {
		self::$acting_user = $user_id;
	}

	/**
	 * The user whose credentials apply right now.
	 *
	 * @return int
	 */
	private static function acting_user_id(): int {
		return null !== self::$acting_user ? self::$acting_user : (int) get_current_user_id();
	}

	/**
	 * Reads one credential/bookkeeping value from the acting credential set.
	 *
	 * @param string $key Key without prefix.
	 * @return string
	 */
	private static function cred_get( string $key ): string {
		$uid = self::acting_user_id();
		if ( $uid <= 0 ) {
			return '';
		}
		return trim( (string) get_user_meta( $uid, self::USER_META_PREFIX . $key, true ) );
	}

	/**
	 * Writes one credential/bookkeeping value into the acting credential set.
	 *
	 * @param string $key   Key without prefix.
	 * @param mixed  $value Value.
	 * @return void
	 */
	private static function cred_update( string $key, $value ): void {
		$uid = self::acting_user_id();
		if ( $uid <= 0 ) {
			return;
		}
		update_user_meta( $uid, self::USER_META_PREFIX . $key, $value );
	}

	/**
	 * Deletes one credential/bookkeeping value from the acting credential set.
	 *
	 * @param string $key Key without prefix.
	 * @return void
	 */
	private static function cred_delete( string $key ): void {
		$uid = self::acting_user_id();
		if ( $uid <= 0 ) {
			return;
		}
		delete_user_meta( $uid, self::USER_META_PREFIX . $key );
	}

	/**
	 * The acting credential set's access token.
	 *
	 * @return string
	 */
	public static function get_access_token(): string {
		return self::cred_get( 'access_token' );
	}

	/**
	 * The acting credential set's target board ID.
	 *
	 * @return string
	 */
	public static function get_board_id(): string {
		return self::cred_get( 'board_id' );
	}

	/**
	 * GET against the Pinterest API.
	 *
	 * @param string $path  Path starting with '/'.
	 * @param array  $query Query args.
	 * @return array|WP_Error Decoded response.
	 */
	private static function api_get( string $path, array $query = array() ): array|WP_Error {

		$url = self::API_BASE . $path;
		if ( $query ) {
			$url = add_query_arg( $query, $url );
		}

		$response = wp_remote_get(
			$url,
			array(
				'timeout' => 20,
				'headers' => array( 'Authorization' => 'Bearer ' . self::get_access_token() ),
			)
		);

		return self::api_response( $response );
	}

	/**
	 * POST (JSON) against the Pinterest API.
	 *
	 * @param string $path Path starting with '/'.
	 * @param array  $body Request body.
	 * @return array|WP_Error Decoded response.
	 */
	private static function api_post( string $path, array $body ): array|WP_Error {

		$response = wp_remote_post(
			self::API_BASE . $path,
			array(
				'timeout' => 30,
				'headers' => array(
					'Authorization' => 'Bearer ' . self::get_access_token(),
					'Content-Type'  => 'application/json',
				),
				'body'    => wp_json_encode( $body ),
			)
		);

		return self::api_response( $response );
	}

	/* ---------------------------------------------------------------------
	 * OAuth: Verbindung im Profil herstellen
	 * ------------------------------------------------------------------ */

	/**
	 * The redirect URI Pinterest sends the user back to.
	 *
	 * Muss in der Pinterest-App unter „Weiterleitungs-URIs" exakt so eingetragen
	 * sein. Bewusst die eigene Profilseite: dort steht der Button, dorthin
	 * gehört die Rückkehr, und es bleibt bei genau einer URI zum Eintragen.
	 *
	 * @return string
	 */
	public static function oauth_redirect_uri(): string {
		return admin_url( 'profile.php' );
	}

	/**
	 * Builds the authorize URL and remembers a one-time state for the return.
	 *
	 * @param int $user_id User who is connecting.
	 * @return string Empty when app credentials are missing.
	 */
	public static function oauth_authorize_url( int $user_id ): string {

		self::set_acting_user( $user_id );
		$app_id = self::cred_get( 'app_id' );
		self::set_acting_user( null );

		if ( '' === $app_id ) {
			return '';
		}

		// State gegen CSRF: zufällig, an den Benutzer gebunden, kurzlebig.
		$state = wp_generate_password( 20, false );
		set_transient( self::OAUTH_STATE_PREFIX . $state, $user_id, 15 * MINUTE_IN_SECONDS );

		return add_query_arg(
			array(
				'client_id'     => rawurlencode( $app_id ),
				'redirect_uri'  => rawurlencode( self::oauth_redirect_uri() ),
				'response_type' => 'code',
				'scope'         => rawurlencode( self::OAUTH_SCOPES ),
				'state'         => rawurlencode( $state ),
			),
			self::OAUTH_AUTHORIZE_URL
		);
	}

	/**
	 * Handles the return from Pinterest: exchanges the code for tokens.
	 *
	 * Läuft auf admin_init, weil die Rückleitung auf profile.php landet. Ohne
	 * gültigen State passiert nichts — dann war es keine Rückkehr von uns.
	 *
	 * @return void
	 */
	public function handle_oauth_callback(): void {

		// phpcs:disable WordPress.Security.NonceVerification.Recommended -- der state-Parameter IST die Absicherung.
		$code  = isset( $_GET['code'] ) ? sanitize_text_field( wp_unslash( $_GET['code'] ) ) : '';
		$state = isset( $_GET['state'] ) ? sanitize_text_field( wp_unslash( $_GET['state'] ) ) : '';
		// phpcs:enable WordPress.Security.NonceVerification.Recommended

		if ( '' === $code || '' === $state ) {
			return;
		}

		$state_key = self::OAUTH_STATE_PREFIX . $state;
		$user_id   = (int) get_transient( $state_key );

		if ( ! $user_id ) {
			return; // Kein State von uns (oder abgelaufen) – nicht unsere Rückkehr.
		}

		// State ist einmalig: sofort entwerten, auch wenn der Tausch scheitert.
		delete_transient( $state_key );

		if ( $user_id !== get_current_user_id() ) {
			self::store_oauth_notice( $user_id, false, __( 'The Pinterest authorization belongs to a different account than the one logged in.', 'mixmymeals' ) );
			return;
		}

		self::set_acting_user( $user_id );
		$result = self::exchange_oauth_code( $code );
		self::set_acting_user( null );

		if ( is_wp_error( $result ) ) {
			self::store_oauth_notice( $user_id, false, $result->get_error_message() );
		} else {
			self::store_oauth_notice( $user_id, true, '' );
		}

		// Code und state aus der Adresszeile nehmen: ein Reload würde sonst
		// denselben — inzwischen verbrauchten — Code erneut einlösen wollen.
		wp_safe_redirect( remove_query_arg( array( 'code', 'state' ), self::oauth_redirect_uri() ) );
		exit;
	}

	/**
	 * Trades an authorization code for an access and refresh token.
	 *
	 * @param string $code Authorization code from the redirect.
	 * @return true|WP_Error
	 */
	private static function exchange_oauth_code( string $code ): bool|WP_Error {

		$app_id = self::cred_get( 'app_id' );
		$secret = self::cred_get( 'app_secret' );

		if ( '' === $app_id || '' === $secret ) {
			return new WP_Error(
				'mmm_pinterest_oauth',
				__( 'App ID and App Secret must be saved before connecting.', 'mixmymeals' )
			);
		}

		$response = wp_remote_post(
			self::API_BASE . '/oauth/token',
			array(
				'timeout' => 20,
				'headers' => array(
					'Authorization' => 'Basic ' . base64_encode( $app_id . ':' . $secret ), // phpcs:ignore WordPress.PHP.DiscouragedPHPFunctions.obfuscation_base64_encode
					'Content-Type'  => 'application/x-www-form-urlencoded',
				),
				'body'    => array(
					'grant_type'   => 'authorization_code',
					'code'         => $code,
					'redirect_uri' => self::oauth_redirect_uri(),
				),
			)
		);

		$data = self::api_response( $response );

		if ( is_wp_error( $data ) ) {
			return $data;
		}

		if ( empty( $data['access_token'] ) ) {
			return new WP_Error(
				'mmm_pinterest_oauth',
				__( 'Pinterest returned no access token.', 'mixmymeals' )
			);
		}

		self::cred_update( 'access_token', (string) $data['access_token'] );
		if ( ! empty( $data['refresh_token'] ) ) {
			self::cred_update( 'refresh_token', (string) $data['refresh_token'] );
		}
		self::cred_update( 'token_refreshed', time() );
		self::cred_delete( 'token_error' );

		// Der zwischengespeicherte Verbindungsstatus gilt für den alten Token —
		// Schlüsselformat wie in token_status().
		delete_transient( 'mmm_pin_status_' . substr( md5( (string) $data['access_token'] ), 0, 12 ) );

		return true;
	}

	/**
	 * Stores the outcome of a connect attempt for the next page load.
	 *
	 * @param int    $user_id User ID.
	 * @param bool   $ok      Success flag.
	 * @param string $message Error message when failed.
	 * @return void
	 */
	private static function store_oauth_notice( int $user_id, bool $ok, string $message ): void {
		set_transient(
			self::OAUTH_STATE_PREFIX . 'notice_' . $user_id,
			array( 'ok' => $ok, 'message' => $message ),
			MINUTE_IN_SECONDS
		);
	}

	/**
	 * Shows the result of the last connect attempt on the profile screen.
	 *
	 * @return void
	 */
	public function oauth_notice(): void {

		$key    = self::OAUTH_STATE_PREFIX . 'notice_' . get_current_user_id();
		$notice = get_transient( $key );

		if ( ! is_array( $notice ) ) {
			return;
		}

		delete_transient( $key );

		printf(
			'<div class="notice notice-%s is-dismissible"><p>%s</p></div>',
			$notice['ok'] ? 'success' : 'error',
			esc_html(
				$notice['ok']
					? __( 'Pinterest connected. Access and refresh token have been stored.', 'mixmymeals' )
					: sprintf(
						/* translators: %s: error message. */
						__( 'Pinterest connection failed: %s', 'mixmymeals' ),
						$notice['message']
					)
			)
		);
	}

	/**
	 * Normalizes a Pinterest API response into array|WP_Error.
	 *
	 * @param array|WP_Error $response HTTP response.
	 * @return array|WP_Error
	 */
	private static function api_response( $response ): array|WP_Error {

		if ( is_wp_error( $response ) ) {
			return $response;
		}

		$code = (int) wp_remote_retrieve_response_code( $response );
		$data = json_decode( (string) wp_remote_retrieve_body( $response ), true );

		if ( $code >= 200 && $code < 300 ) {
			return is_array( $data ) ? $data : array();
		}

		/*
		 * Pinterest liefert die eigentliche Ursache im Feld "message", oft mit
		 * einem eigenen Fehlercode. Beides mitnehmen und um einen Klartext-
		 * Hinweis ergänzen — "HTTP 401" allein hilft beim Beheben nicht weiter.
		 */
		$detail = '';
		if ( is_array( $data ) ) {
			if ( ! empty( $data['message'] ) ) {
				$detail = (string) $data['message'];
			}
			if ( isset( $data['code'] ) && '' !== (string) $data['code'] ) {
				$detail .= sprintf( ' (Pinterest-Code %s)', (string) $data['code'] );
			}
		}

		if ( '' === trim( $detail ) ) {
			// Kein verwertbarer JSON-Body: wenigstens den Anfang der Antwort
			// zeigen, sonst steht da nur eine nackte Zahl.
			$raw    = trim( wp_strip_all_tags( (string) wp_remote_retrieve_body( $response ) ) );
			$detail = '' !== $raw
				? mb_substr( $raw, 0, 200 )
				: (string) wp_remote_retrieve_response_message( $response );
		}

		// Pinterest beendet seine Meldungen mal mit Punkt, mal nicht — ohne
		// Ausgleich klebt der folgende Hinweis als ein Satz daran.
		$detail = rtrim( trim( $detail ), '.' ) . '.';

		$message = sprintf(
			/* translators: 1: HTTP status code, 2: error detail from the Pinterest API. */
			__( 'Pinterest API: HTTP %1$d – %2$s', 'mixmymeals' ),
			$code,
			$detail
		);

		$hint = self::api_error_hint( $code, $detail );
		if ( '' !== $hint ) {
			$message .= ' ' . $hint;
		}

		return new WP_Error( 'mmm_pinterest_api', $message, array( 'status' => $code ) );
	}

	/**
	 * Plain-language hint for a failed Pinterest call.
	 *
	 * Die Meldung wird VOR dem HTTP-Status ausgewertet: Pinterest antwortet bei
	 * fehlenden Scopes mit 401, obwohl der Token weder abgelaufen noch ungültig
	 * ist. Ein rein statusbasierter Hinweis würde hier "Token neu hinterlegen"
	 * raten — und der neue Token hätte exakt dasselbe Problem.
	 *
	 * @param int    $code   HTTP status code.
	 * @param string $detail Error text as returned by the API.
	 * @return string Empty when there is nothing useful to add.
	 */
	private static function api_error_hint( int $code, string $detail ): string {

		$says_scopes = false !== stripos( $detail, 'scope' )
			|| false !== stripos( $detail, 'sufficient permission' );

		if ( $says_scopes ) {
			/*
			 * Welche Scopes fehlen, steht bereits in der Meldung darüber — hier
			 * nichts behaupten, sondern nur sagen, wie man sie bekommt. Ein
			 * fester Text über „Schreibrechte" wäre falsch, sobald ein
			 * Leserecht fehlt.
			 */
			return __( 'Reconnect: use “Connect with Pinterest” in your profile — it requests the full set of scopes this plugin needs. Tokens from the “Generate access token” button on the developer platform never have write scopes.', 'mixmymeals' );
		}

		$hints = array(
			400 => __( 'The request was rejected — often the image is not publicly reachable (localhost will not work) or title/description are too long.', 'mixmymeals' ),
			401 => __( 'Credentials rejected — the token is invalid, expired, or lacks the required scopes.', 'mixmymeals' ),
			403 => __( 'Access denied — the token lacks the required scopes or the board belongs to another account.', 'mixmymeals' ),
			404 => __( 'Not found — the configured board no longer exists. Select a new one in your profile.', 'mixmymeals' ),
			429 => __( 'Rate limit reached — Pinterest is throttling. Try again later.', 'mixmymeals' ),
		);

		if ( isset( $hints[ $code ] ) ) {
			return $hints[ $code ];
		}

		if ( $code >= 500 ) {
			return __( 'Server error at Pinterest — not caused by your data, try again later.', 'mixmymeals' );
		}

		return '';
	}

	/**
	 * Connection status (cached for 10 minutes, keyed by token).
	 *
	 * @param bool $force Skip the cache.
	 * @return array{ok:bool, username:string, error:string}
	 */
	public static function token_status( bool $force = false ): array {

		$token = self::get_access_token();

		if ( '' === $token ) {
			return array(
				'ok'       => false,
				'username' => '',
				'error'    => __( 'No access token configured.', 'mixmymeals' ),
			);
		}

		$cache_key = 'mmm_pin_status_' . substr( md5( $token ), 0, 12 );

		if ( ! $force ) {
			$cached = get_transient( $cache_key );
			if ( is_array( $cached ) ) {
				return $cached;
			}
		}

		$response = self::api_get( '/user_account' );

		if ( is_wp_error( $response ) ) {
			$status = array(
				'ok'       => false,
				'username' => '',
				'error'    => $response->get_error_message(),
			);
		} else {
			$status = array(
				'ok'       => true,
				'username' => (string) ( $response['username'] ?? '' ),
				'error'    => '',
			);
		}

		set_transient( $cache_key, $status, 10 * MINUTE_IN_SECONDS );

		return $status;
	}

	/**
	 * The user's boards (id + name), cached for 10 minutes. Used in the
	 * settings to help picking the board ID.
	 *
	 * @return array[] Arrays with 'id' and 'name'; empty on error.
	 */
	public static function boards(): array {

		if ( '' === self::get_access_token() ) {
			return array();
		}

		$cache_key = 'mmm_pin_boards_' . substr( md5( self::get_access_token() ), 0, 12 );

		$cached = get_transient( $cache_key );
		if ( is_array( $cached ) ) {
			return $cached;
		}

		$response = self::api_get( '/boards', array( 'page_size' => 50 ) );
		$boards   = array();

		if ( ! is_wp_error( $response ) && ! empty( $response['items'] ) ) {
			foreach ( $response['items'] as $item ) {
				$boards[] = array(
					'id'   => (string) ( $item['id'] ?? '' ),
					'name' => (string) ( $item['name'] ?? '' ),
				);
			}
		}

		set_transient( $cache_key, $boards, 10 * MINUTE_IN_SECONDS );

		return $boards;
	}

	/**
	 * Refreshes the access token via the OAuth refresh flow when app
	 * credentials and a refresh token are configured. Runs on the daily cron;
	 * refreshes once the token is older than 7 days (Pinterest access tokens
	 * live for 30).
	 *
	 * @return void
	 */
	public static function maybe_refresh_token(): void {

		// Refresh every user's own token.
		$user_ids = get_users(
			array(
				'fields'       => 'ID',
				'meta_key'     => self::USER_META_PREFIX . 'access_token', // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key
				'meta_compare' => 'EXISTS',
			)
		);
		foreach ( $user_ids as $uid ) {
			self::set_acting_user( (int) $uid );
			self::maybe_refresh_acting_token();
		}

		self::set_acting_user( null );
	}

	/**
	 * Refreshes the ACTING credential set's token when due (requires app
	 * credentials and a refresh token in the same set).
	 *
	 * @return void
	 */
	private static function maybe_refresh_acting_token(): void {

		$app_id  = self::cred_get( 'app_id' );
		$secret  = self::cred_get( 'app_secret' );
		$refresh = self::cred_get( 'refresh_token' );

		if ( '' === $app_id || '' === $secret || '' === $refresh || '' === self::get_access_token() ) {
			return;
		}

		$last = (int) self::cred_get( 'token_refreshed' );
		if ( $last && ( time() - $last ) < 7 * DAY_IN_SECONDS ) {
			return;
		}

		$response = wp_remote_post(
			self::API_BASE . '/oauth/token',
			array(
				'timeout' => 20,
				'headers' => array(
					'Authorization' => 'Basic ' . base64_encode( $app_id . ':' . $secret ), // phpcs:ignore WordPress.PHP.DiscouragedPHPFunctions.obfuscation_base64_encode
					'Content-Type'  => 'application/x-www-form-urlencoded',
				),
				'body'    => array(
					'grant_type'    => 'refresh_token',
					'refresh_token' => $refresh,
				),
			)
		);

		$data = self::api_response( $response );

		if ( is_wp_error( $data ) || empty( $data['access_token'] ) ) {
			$message = is_wp_error( $data ) ? $data->get_error_message() : __( 'Unexpected response from the Pinterest API.', 'mixmymeals' );
			self::cred_update( 'token_error', $message );
			mmm_write_to_log( 'MixMyMeals Pinterest token refresh failed: ' . $message );
			return;
		}

		self::cred_update( 'access_token', (string) $data['access_token'] );
		if ( ! empty( $data['refresh_token'] ) ) {
			self::cred_update( 'refresh_token', (string) $data['refresh_token'] );
		}
		self::cred_update( 'token_refreshed', time() );
		self::cred_delete( 'token_error' );
	}

	/* ---------------------------------------------------------------------
	 * Pin content (image, title, description)
	 * ------------------------------------------------------------------ */

	/**
	 * The pin image for a post: recipes use their single Instagram image,
	 * plans the cover (or the overview when the cover slide is disabled).
	 *
	 * @param int $post_id Plan or recipe post ID.
	 * @return array{file:string, path:string, url:string}
	 */
	private static function pin_image_spec( int $post_id ): array {

		if ( get_post_type( $post_id ) === self::RECIPE_POST_TYPE ) {
			$file = 'rezept.jpg';
		} else {
			$use_cover = 'off' !== (string) get_option( 'mixmymeals_instagram_show_cover', 'on' );
			$file      = $use_cover ? 'cover.jpg' : 'uebersicht.jpg';
		}

		$path = trailingslashit( Mixmymeals_Instagram::get_plan_dir( $post_id ) ) . $file;
		$url  = trailingslashit( Mixmymeals_Instagram::get_plan_url( $post_id ) ) . $file;

		return array(
			'file' => $file,
			'path' => $path,
			'url'  => $url,
		);
	}

	/**
	 * Renders the pin image freshly via the Instagram renderer.
	 *
	 * @param int $post_id Plan or recipe post ID.
	 * @return string|WP_Error Absolute image path.
	 */
	private function render_pin_image( int $post_id ): string|WP_Error {

		$renderer = Mixmymeals_Instagram::instance();

		if ( get_post_type( $post_id ) === self::RECIPE_POST_TYPE ) {
			return $renderer->render_recipe( $post_id );
		}

		$use_cover = 'off' !== (string) get_option( 'mixmymeals_instagram_show_cover', 'on' );

		return $use_cover ? $renderer->render_cover( $post_id ) : $renderer->render_overview( $post_id );
	}

	/**
	 * Default pin title: the post title, within Pinterest's limit.
	 *
	 * @param int $post_id Post ID.
	 * @return string
	 */
	public static function default_title( int $post_id ): string {
		return mb_substr( html_entity_decode( get_the_title( $post_id ), ENT_QUOTES, 'UTF-8' ), 0, self::TITLE_MAX );
	}

	/**
	 * Default pin description: excerpt, then trimmed content, then tagline.
	 *
	 * @param int $post_id Post ID.
	 * @return string
	 */
	public static function default_description( int $post_id ): string {

		$post = get_post( $post_id );
		$text = '';

		if ( $post ) {
			$text = trim( wp_strip_all_tags( strip_shortcodes( $post->post_excerpt ) ) );
			if ( '' === $text ) {
				$text = trim( wp_strip_all_tags( strip_shortcodes( $post->post_content ) ) );
			}
		}
		if ( '' === $text ) {
			$text = (string) get_bloginfo( 'description' );
		}

		$text = preg_replace( '/\s+/u', ' ', html_entity_decode( $text, ENT_QUOTES, 'UTF-8' ) );

		return mb_substr( trim( (string) $text ), 0, self::DESC_MAX );
	}

	/* ---------------------------------------------------------------------
	 * Publishing
	 * ------------------------------------------------------------------ */

	/**
	 * Renders a fresh image and creates the pin. The pin links back to the
	 * plan/recipe page.
	 *
	 * @param int    $post_id     Plan or recipe post ID.
	 * @param string $title       Pin title.
	 * @param string $description Pin description.
	 * @return string|WP_Error Pin URL.
	 */
	public function publish_now( int $post_id, string $title, string $description ): string|WP_Error {

		if ( '' === self::get_access_token() ) {
			return new WP_Error(
				'mmm_pinterest_token',
				__( 'No access token stored. Pinterest credentials are per user, in your own profile under “MixMyMeals: Social accounts”.', 'mixmymeals' )
			);
		}

		$board_id = self::get_board_id();
		if ( '' === $board_id ) {
			return new WP_Error(
				'mmm_pinterest_board',
				__( 'No board selected. Pick one in your own profile under “MixMyMeals: Social accounts”.', 'mixmymeals' )
			);
		}

		// Schritt benennen: Ein Fehler beim Bild ist etwas anderes als ein
		// Fehler bei Pinterest, und die Ursache liegt dann bei uns.
		$rendered = $this->render_pin_image( $post_id );
		if ( is_wp_error( $rendered ) ) {
			return new WP_Error(
				$rendered->get_error_code(),
				sprintf(
					/* translators: %s: underlying error message. */
					__( 'The image could not be created: %s', 'mixmymeals' ),
					$rendered->get_error_message()
				),
				$rendered->get_error_data()
			);
		}

		$spec = self::pin_image_spec( $post_id );

		$title       = mb_substr( trim( $title ), 0, self::TITLE_MAX );
		$description = mb_substr( trim( $description ), 0, self::DESC_MAX );
		if ( '' === $title ) {
			$title = self::default_title( $post_id );
		}

		$response = self::api_post(
			'/pins',
			array(
				'board_id'     => $board_id,
				'title'        => $title,
				'description'  => $description,
				'link'         => get_permalink( $post_id ),
				'media_source' => array(
					'source_type' => 'image_url',
					'url'         => $spec['url'] . '?v=' . time(),
				),
			)
		);

		if ( is_wp_error( $response ) ) {
			return $response;
		}

		$pin_id = (string) ( $response['id'] ?? '' );
		if ( '' === $pin_id ) {
			// HTTP 2xx, aber keine Pin-ID: zeigen, was stattdessen kam.
			return new WP_Error(
				'mmm_pinterest_api',
				sprintf(
					/* translators: %s: keys returned by the API. */
					__( 'Pinterest acknowledged the pin but returned no pin ID. Response fields: %s', 'mixmymeals' ),
					implode( ', ', array_keys( $response ) ) ?: '(leer)'
				)
			);
		}

		return 'https://www.pinterest.com/pin/' . rawurlencode( $pin_id ) . '/';
	}

	/**
	 * Stores the outcome of a (scheduled or immediate) pin attempt.
	 *
	 * @param int    $post_id Post ID.
	 * @param bool   $ok      Success flag.
	 * @param string $message Error message when failed.
	 * @param string $pin_url Pin URL when succeeded.
	 * @return void
	 */
	private static function store_result( int $post_id, bool $ok, string $message, string $pin_url ): void {
		update_post_meta(
			$post_id,
			self::META_LAST_RESULT,
			array(
				'ok'      => $ok,
				'time'    => time(),
				'message' => $message,
				'pin_url' => $pin_url,
			)
		);
	}

	/* ---------------------------------------------------------------------
	 * Scheduling
	 * ------------------------------------------------------------------ */

	/**
	 * Removes every pending scheduled pin event for one post.
	 *
	 * @param int $post_id Post ID.
	 * @return void
	 */
	public static function unschedule_publish( int $post_id ): void {
		while ( false !== wp_next_scheduled( self::PUBLISH_HOOK, array( $post_id ) ) ) {
			wp_unschedule_event( (int) wp_next_scheduled( self::PUBLISH_HOOK, array( $post_id ) ), self::PUBLISH_HOOK, array( $post_id ) );
		}
	}

	/**
	 * Cron callback: renders a fresh image and creates the scheduled pin.
	 *
	 * @param int $post_id Post ID.
	 * @return void
	 */
	public function run_scheduled_publish( int $post_id ): void {

		$title = (string) get_post_meta( $post_id, self::META_SCHEDULED_TITLE, true );
		$desc  = (string) get_post_meta( $post_id, self::META_SCHEDULED_DESC, true );

		// Pin with the credentials of whoever scheduled it.
		$scheduled_by = (int) get_post_meta( $post_id, self::META_SCHEDULED_USER, true );
		self::set_acting_user( $scheduled_by > 0 ? $scheduled_by : 0 );

		$result = $this->publish_now( $post_id, $title, $desc );

		self::set_acting_user( null );

		if ( is_wp_error( $result ) ) {
			self::store_result( $post_id, false, $result->get_error_message(), '' );
			mmm_write_to_log( 'MixMyMeals Pinterest scheduled pin failed for #' . $post_id . ': ' . $result->get_error_message() );
		} else {
			self::store_result( $post_id, true, '', (string) $result );
		}

		delete_post_meta( $post_id, self::META_SCHEDULED_AT );
		delete_post_meta( $post_id, self::META_SCHEDULED_TITLE );
		delete_post_meta( $post_id, self::META_SCHEDULED_DESC );
		delete_post_meta( $post_id, self::META_SCHEDULED_USER );
	}

	/* ---------------------------------------------------------------------
	 * AJAX
	 * ------------------------------------------------------------------ */

	/**
	 * Shared AJAX guard: nonce, capability, post type, token.
	 *
	 * @return int Validated post ID (dies on failure).
	 */
	private function ajax_guard(): int {

		$post_id = isset( $_POST['post_id'] ) ? absint( $_POST['post_id'] ) : 0;

		if ( ! check_ajax_referer( self::NONCE_ACTION, 'nonce', false )
			|| ! $post_id
			|| ! current_user_can( 'edit_post', $post_id )
			|| ! in_array( get_post_type( $post_id ), array( self::POST_TYPE, self::RECIPE_POST_TYPE ), true )
		) {
			wp_send_json_error( array( 'message' => __( 'Not allowed.', 'mixmymeals' ) ), 403 );
		}

		if ( '' === self::get_access_token() ) {
			wp_send_json_error( array( 'message' => __( 'No access token configured.', 'mixmymeals' ) ), 400 );
		}

		return $post_id;
	}

	/**
	 * AJAX: pins immediately with the submitted title/description.
	 *
	 * @return void
	 */
	public function ajax_pin(): void {

		$post_id = $this->ajax_guard();

		$title = isset( $_POST['title'] ) ? sanitize_text_field( wp_unslash( $_POST['title'] ) ) : '';
		$desc  = isset( $_POST['description'] ) ? sanitize_textarea_field( wp_unslash( $_POST['description'] ) ) : '';

		$result = $this->publish_now( $post_id, $title, $desc );

		if ( is_wp_error( $result ) ) {
			self::store_result( $post_id, false, $result->get_error_message(), '' );
			wp_send_json_error( array( 'message' => $result->get_error_message() ), 500 );
		}

		self::store_result( $post_id, true, '', (string) $result );
		wp_send_json_success( array( 'pin_url' => (string) $result ) );
	}

	/**
	 * AJAX: schedules a pin.
	 *
	 * @return void
	 */
	public function ajax_schedule(): void {

		$post_id = $this->ajax_guard();

		$when  = isset( $_POST['when'] ) ? sanitize_text_field( wp_unslash( $_POST['when'] ) ) : '';
		$title = isset( $_POST['title'] ) ? sanitize_text_field( wp_unslash( $_POST['title'] ) ) : '';
		$desc  = isset( $_POST['description'] ) ? sanitize_textarea_field( wp_unslash( $_POST['description'] ) ) : '';

		$dt = $when ? date_create_immutable( $when, wp_timezone() ) : false;

		if ( ! $dt ) {
			wp_send_json_error( array( 'message' => __( 'Please pick a valid date and time.', 'mixmymeals' ) ), 400 );
		}

		$timestamp = $dt->getTimestamp();

		if ( $timestamp < time() + MINUTE_IN_SECONDS ) {
			wp_send_json_error( array( 'message' => __( 'The scheduled time must be in the future.', 'mixmymeals' ) ), 400 );
		}

		self::unschedule_publish( $post_id );

		update_post_meta( $post_id, self::META_SCHEDULED_AT, $timestamp );
		update_post_meta( $post_id, self::META_SCHEDULED_TITLE, mb_substr( $title, 0, self::TITLE_MAX ) );
		update_post_meta( $post_id, self::META_SCHEDULED_DESC, mb_substr( $desc, 0, self::DESC_MAX ) );
		update_post_meta( $post_id, self::META_SCHEDULED_USER, get_current_user_id() );

		wp_schedule_single_event( $timestamp, self::PUBLISH_HOOK, array( $post_id ) );

		wp_send_json_success(
			array(
				'scheduled' => wp_date( get_option( 'date_format' ) . ' H:i', $timestamp ),
			)
		);
	}

	/**
	 * AJAX: cancels a scheduled pin.
	 *
	 * @return void
	 */
	public function ajax_unschedule(): void {

		$post_id = $this->ajax_guard();

		self::unschedule_publish( $post_id );
		delete_post_meta( $post_id, self::META_SCHEDULED_AT );
		delete_post_meta( $post_id, self::META_SCHEDULED_TITLE );
		delete_post_meta( $post_id, self::META_SCHEDULED_DESC );
		delete_post_meta( $post_id, self::META_SCHEDULED_USER );

		wp_send_json_success();
	}

	/* ---------------------------------------------------------------------
	 * Meta box
	 * ------------------------------------------------------------------ */

	/**
	 * Registers the Pinterest meta box on plans and recipes.
	 *
	 * @return void
	 */
	public function add_meta_box(): void {
		add_meta_box(
			'mmm_pinterest_box',
			__( 'Pinterest', 'mixmymeals' ),
			array( $this, 'render_meta_box' ),
			array( self::POST_TYPE, self::RECIPE_POST_TYPE ),
			'normal',
			'low'
		);
	}

	/**
	 * Enqueues the admin script on the plan/recipe edit screens.
	 *
	 * @param string $hook Current admin page hook.
	 * @return void
	 */
	public function enqueue_assets( string $hook ): void {

		$is_edit_screen = in_array( $hook, array( 'post.php', 'post-new.php' ), true )
			&& get_current_screen()
			&& in_array( get_current_screen()->post_type, array( self::POST_TYPE, self::RECIPE_POST_TYPE ), true );

		if ( ! $is_edit_screen ) {
			return;
		}

		$plugin  = mixmymeals();
		$rel     = 'js/pinterest-admin' . $plugin->script_suffix . '.js';
		$abs     = trailingslashit( $plugin->assets_dir ) . $rel;
		$version = file_exists( $abs ) ? (string) filemtime( $abs ) : $plugin->_version;

		wp_enqueue_script(
			$plugin->_token . '-pinterest-admin',
			esc_url( $plugin->assets_url ) . $rel,
			array( 'jquery' ),
			$version,
			array( 'in_footer' => true )
		);
	}

	/**
	 * Renders the meta box: connection status, pin title/description,
	 * immediate pinning and scheduling.
	 *
	 * @param WP_Post $post Current post.
	 * @return void
	 */
	public function render_meta_box( WP_Post $post ): void {

		if ( '' === self::get_access_token() ) {
			printf(
				'<p class="description">%s <a href="%s">%s</a></p>',
				esc_html__( 'To pin plans and recipes, add your Pinterest access token on your profile.', 'mixmymeals' ),
				esc_url( get_edit_profile_url() ),
				esc_html__( 'Open profile', 'mixmymeals' )
			);
			return;
		}

		$status = self::token_status();
		if ( ! $status['ok'] ) {
			printf(
				'<div class="notice notice-error inline"><p>%s</p></div>',
				esc_html(
					sprintf(
						/* translators: %s: error message. */
						__( 'Pinterest connection error: %s', 'mixmymeals' ),
						$status['error']
					)
				)
			);
			return;
		}

		if ( '' === self::get_board_id() ) {
			printf(
				'<div class="notice notice-warning inline"><p>%s <a href="%s">%s</a></p></div>',
				esc_html__( 'No board configured yet — choose a board ID on your profile.', 'mixmymeals' ),
				esc_url( get_edit_profile_url() ),
				esc_html__( 'Open profile', 'mixmymeals' )
			);
			return;
		}

		printf(
			'<div id="mmm-pinterest-box" data-post="%d" data-nonce="%s">',
			(int) $post->ID,
			esc_attr( wp_create_nonce( self::NONCE_ACTION ) )
		);

		printf(
			'<p class="description">%s</p>',
			esc_html(
				sprintf(
					/* translators: %s: Pinterest user name. */
					__( 'Connected as @%s. The pin image is generated freshly when pinning and links to this page.', 'mixmymeals' ),
					$status['username']
				)
			)
		);

		// Preview of the current pin image, when one exists already.
		$spec = self::pin_image_spec( $post->ID );
		if ( is_file( $spec['path'] ) ) {
			printf(
				'<p><img src="%s" alt="" style="max-width:180px;height:auto;border-radius:6px;" /></p>',
				esc_url( $spec['url'] . '?v=' . (int) filemtime( $spec['path'] ) )
			);
		}

		printf(
			'<p><label for="mmm-pinterest-title"><strong>%s</strong></label><br /><input type="text" id="mmm-pinterest-title" maxlength="%d" style="width:100%%;" value="%s" /></p>',
			esc_html__( 'Pin title', 'mixmymeals' ),
			(int) self::TITLE_MAX,
			esc_attr( self::default_title( $post->ID ) )
		);

		printf(
			'<p><label for="mmm-pinterest-desc"><strong>%s</strong></label><br /><textarea id="mmm-pinterest-desc" rows="4" maxlength="%d" style="width:100%%;">%s</textarea></p>',
			esc_html__( 'Pin description', 'mixmymeals' ),
			(int) self::DESC_MAX,
			esc_textarea( self::default_description( $post->ID ) )
		);

		printf(
			'<p><button type="button" class="button button-primary" id="mmm-pinterest-pin">%s</button> <span id="mmm-pinterest-status"></span></p>',
			esc_html__( 'Pin now', 'mixmymeals' )
		);

		// Scheduling.
		printf( '<h4 style="margin:18px 0 6px;">%s</h4>', esc_html__( 'Schedule pin', 'mixmymeals' ) );

		$scheduled_at = (int) get_post_meta( $post->ID, self::META_SCHEDULED_AT, true );

		if ( $scheduled_at ) {
			printf(
				'<p>%s <button type="button" class="button" id="mmm-pinterest-unschedule">%s</button> <span id="mmm-pinterest-schedule-status"></span></p>',
				esc_html(
					sprintf(
						/* translators: %s: formatted date and time. */
						__( 'Pin scheduled for %s — the image is regenerated right before pinning.', 'mixmymeals' ),
						wp_date( get_option( 'date_format' ) . ' H:i', $scheduled_at )
					)
				),
				esc_html__( 'Cancel schedule', 'mixmymeals' )
			);
		} else {
			printf(
				'<p><input type="datetime-local" id="mmm-pinterest-when" min="%s" /> <button type="button" class="button" id="mmm-pinterest-schedule">%s</button> <span id="mmm-pinterest-schedule-status"></span></p><p class="description">%s</p>',
				esc_attr( wp_date( 'Y-m-d\TH:i', time() + 10 * MINUTE_IN_SECONDS ) ),
				esc_html__( 'Schedule', 'mixmymeals' ),
				esc_html__( 'At the scheduled time the image is regenerated and the pin is created with the title and description above. Runs via WP-Cron, so the exact minute can shift slightly.', 'mixmymeals' )
			);
		}

		$last = get_post_meta( $post->ID, self::META_LAST_RESULT, true );
		if ( is_array( $last ) && isset( $last['ok'] ) ) {
			if ( $last['ok'] ) {
				printf(
					'<p class="description" style="color:#008a20;">%s <a href="%s" target="_blank" rel="noopener">%s</a></p>',
					esc_html(
						sprintf(
							/* translators: %s: formatted date and time. */
							__( 'Pinned on %s.', 'mixmymeals' ),
							wp_date( get_option( 'date_format' ) . ' H:i', (int) $last['time'] )
						)
					),
					esc_url( (string) $last['pin_url'] ),
					esc_html__( 'View pin', 'mixmymeals' )
				);
			} else {
				printf(
					'<p class="description" style="color:#d63638;">%s</p>',
					esc_html(
						sprintf(
							/* translators: 1: formatted date and time, 2: error message. */
							__( 'Last pin attempt failed on %1$s: %2$s', 'mixmymeals' ),
							wp_date( get_option( 'date_format' ) . ' H:i', (int) $last['time'] ),
							(string) $last['message']
						)
					)
				);
			}
		}

		echo '</div>';
	}

	/* ---------------------------------------------------------------------
	 * REST API (mixmymeals/v1/pinterest/…)
	 * ------------------------------------------------------------------ */

	/**
	 * Registers the Pinterest REST routes (automation / MCP).
	 *
	 * @return void
	 */
	public function register_rest_routes(): void {

		$ns   = 'mixmymeals/v1';
		$perm = function ( $request ) {
			$id = (int) $request['id'];
			return $id
				&& current_user_can( 'edit_post', $id )
				&& in_array( get_post_type( $id ), array( self::POST_TYPE, self::RECIPE_POST_TYPE ), true );
		};
		$id_arg = array( 'validate_callback' => static fn( $v ) => is_numeric( $v ), 'sanitize_callback' => 'absint' );

		register_rest_route( $ns, '/pinterest/(?P<id>\d+)', array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => array( $this, 'rest_status' ),
			'permission_callback' => $perm,
			'args'                => array( 'id' => $id_arg ),
		) );

		register_rest_route( $ns, '/pinterest/(?P<id>\d+)/publish', array(
			'methods'             => WP_REST_Server::CREATABLE,
			'callback'            => array( $this, 'rest_publish' ),
			'permission_callback' => $perm,
			'args'                => array(
				'id'          => $id_arg,
				'title'       => array( 'required' => false, 'type' => 'string' ),
				'description' => array( 'required' => false, 'type' => 'string' ),
			),
		) );

		register_rest_route( $ns, '/pinterest/(?P<id>\d+)/schedule', array(
			'methods'             => WP_REST_Server::CREATABLE,
			'callback'            => array( $this, 'rest_schedule' ),
			'permission_callback' => $perm,
			'args'                => array(
				'id'          => $id_arg,
				'when'        => array( 'required' => true, 'type' => 'string' ),
				'title'       => array( 'required' => false, 'type' => 'string' ),
				'description' => array( 'required' => false, 'type' => 'string' ),
			),
		) );

		register_rest_route( $ns, '/pinterest/(?P<id>\d+)/unschedule', array(
			'methods'             => WP_REST_Server::CREATABLE,
			'callback'            => array( $this, 'rest_unschedule' ),
			'permission_callback' => $perm,
			'args'                => array( 'id' => $id_arg ),
		) );
	}

	/**
	 * GET /pinterest/{id} — connection, defaults, schedule and last result.
	 *
	 * @param WP_REST_Request $request Request.
	 * @return WP_REST_Response
	 */
	public function rest_status( WP_REST_Request $request ): WP_REST_Response {

		$id        = (int) $request['id'];
		$status    = self::token_status();
		$scheduled = (int) get_post_meta( $id, self::META_SCHEDULED_AT, true );
		$last      = get_post_meta( $id, self::META_LAST_RESULT, true );
		$spec      = self::pin_image_spec( $id );

		return new WP_REST_Response( array(
			'id'           => $id,
			'post_type'    => get_post_type( $id ),
			'title'        => self::default_title( $id ),
			'description'  => self::default_description( $id ),
			'link'         => get_permalink( $id ),
			'connection'   => $status,
			'board_id'     => self::get_board_id(),
			'image_exists' => is_file( $spec['path'] ),
			'scheduled_at' => $scheduled ? wp_date( 'c', $scheduled ) : null,
			'last_result'  => is_array( $last ) && isset( $last['ok'] ) ? array(
				'ok'      => (bool) $last['ok'],
				'time'    => isset( $last['time'] ) ? wp_date( 'c', (int) $last['time'] ) : null,
				'message' => (string) ( $last['message'] ?? '' ),
				'pin_url' => (string) ( $last['pin_url'] ?? '' ),
			) : null,
		), 200 );
	}

	/**
	 * POST /pinterest/{id}/publish — creates the pin now.
	 *
	 * @param WP_REST_Request $request Request.
	 * @return WP_REST_Response|WP_Error
	 */
	public function rest_publish( WP_REST_Request $request ): WP_REST_Response|WP_Error {

		$id    = (int) $request['id'];
		$title = $request->has_param( 'title' )
			? sanitize_text_field( (string) $request->get_param( 'title' ) )
			: self::default_title( $id );
		$desc  = $request->has_param( 'description' )
			? sanitize_textarea_field( (string) $request->get_param( 'description' ) )
			: self::default_description( $id );

		$result = $this->publish_now( $id, $title, $desc );

		if ( is_wp_error( $result ) ) {
			self::store_result( $id, false, $result->get_error_message(), '' );
			return $result;
		}

		self::store_result( $id, true, '', (string) $result );

		return new WP_REST_Response( array(
			'id'      => $id,
			'pin_url' => (string) $result,
		), 200 );
	}

	/**
	 * POST /pinterest/{id}/schedule — schedules a pin.
	 *
	 * @param WP_REST_Request $request Request.
	 * @return WP_REST_Response|WP_Error
	 */
	public function rest_schedule( WP_REST_Request $request ): WP_REST_Response|WP_Error {

		$id   = (int) $request['id'];
		$when = (string) $request->get_param( 'when' );
		$dt   = $when ? date_create_immutable( $when, wp_timezone() ) : false;

		if ( ! $dt ) {
			return new WP_Error( 'mmm_pin_when', __( 'Please pick a valid date and time.', 'mixmymeals' ), array( 'status' => 400 ) );
		}

		$timestamp = $dt->getTimestamp();
		if ( $timestamp < time() + MINUTE_IN_SECONDS ) {
			return new WP_Error( 'mmm_pin_when', __( 'The scheduled time must be in the future.', 'mixmymeals' ), array( 'status' => 400 ) );
		}

		$title = $request->has_param( 'title' )
			? sanitize_text_field( (string) $request->get_param( 'title' ) )
			: self::default_title( $id );
		$desc  = $request->has_param( 'description' )
			? sanitize_textarea_field( (string) $request->get_param( 'description' ) )
			: self::default_description( $id );

		self::unschedule_publish( $id );

		update_post_meta( $id, self::META_SCHEDULED_AT, $timestamp );
		update_post_meta( $id, self::META_SCHEDULED_TITLE, mb_substr( $title, 0, self::TITLE_MAX ) );
		update_post_meta( $id, self::META_SCHEDULED_DESC, mb_substr( $desc, 0, self::DESC_MAX ) );
		update_post_meta( $id, self::META_SCHEDULED_USER, get_current_user_id() );

		wp_schedule_single_event( $timestamp, self::PUBLISH_HOOK, array( $id ) );

		return new WP_REST_Response( array(
			'id'           => $id,
			'scheduled_at' => wp_date( 'c', $timestamp ),
		), 200 );
	}

	/**
	 * POST /pinterest/{id}/unschedule — cancels a scheduled pin.
	 *
	 * @param WP_REST_Request $request Request.
	 * @return WP_REST_Response
	 */
	public function rest_unschedule( WP_REST_Request $request ): WP_REST_Response {

		$id = (int) $request['id'];

		self::unschedule_publish( $id );
		delete_post_meta( $id, self::META_SCHEDULED_AT );
		delete_post_meta( $id, self::META_SCHEDULED_TITLE );
		delete_post_meta( $id, self::META_SCHEDULED_DESC );
		delete_post_meta( $id, self::META_SCHEDULED_USER );

		return new WP_REST_Response( array(
			'id'           => $id,
			'scheduled_at' => null,
		), 200 );
	}
}
